#include <cmath>

using namespace std;

int main() {
    // Define the points
    double x1 = 2;
    double y1 = 16;
    double x2 = -8;
    double y2 = -4;

    // Calculate the slope of the line
    double slope = (y2 - y1) / (x2 - x1);

    // Calculate the y-intercept
    double yIntercept = y1 - slope * x1;

    // Calculate the point where the line intersects the y-axis
    double xIntercept = 0;
    double yIntercept = slope * xIntercept + yIntercept;

    // Print the result
