#include <iostream>
#include <cmath>
using namespace std;

int main() {
    double a, b, c;
    cout << "Enter the values of a, b, and c: ";
    cin >> a >> b >> c;

    // Check if a, b, and c form a geometric sequence
    if (a * b == c) {
        // Check if log_c a, log_b c, and log_a b form an arithmetic sequence
        double log_c_a = log(a) / log(c);
        double log_b_c = log(c) / log(b);
        double log_a_b = log(b) / log(a);

        if (log_b_c - log_c_a == log_a_b - log_b_c) {
            // Calculate the common difference of the arithmetic sequence
            double common_difference = log_a_b - log_b_c;
            cout << "The common difference of the arithmetic sequence is: " << common_difference << endl;
        } else {
            cout << "The given numbers do not form an arithmetic sequence." << endl;
        }
    } else {
        cout << "The given numbers do not form a geometric sequence." << endl;
    }

    return 0;
}

