using namespace std;

int main() {
    double r, s, t;
    double a = 8, b = 1001, c = 2008;

    // Solve the cubic equation
    double discriminant = b * b - 4 * a * c;
    if (discriminant < 0) {
        cout << "No real roots" << endl;
        return 1;
    }

    double root1 = (-b + sqrt(discriminant)) / (2 * a);
    double root2 = (-b - sqrt(discriminant)) / (2 * a);
    double root3 = c / (8 * a);

    // Find the sum of the cubes of the roots
    double sum_of_cubes = pow(root1 + root2, 3) + pow(root2 + root3, 3) + pow(root3 + root1, 3);

    cout << "The sum of the cubes of the roots is: " << sum_of_cubes << endl;

    return 0;
}

